INSERT INTO `article` (`id`, `type`, `status`, `title`, `content`, `cover`, `author_id`, `is_discard`, `view_count`, `like_count`, `share_count`, `publish_time`, `create_time`, `update_time`) VALUES
    (3000000000000006001, 'KNOWLEDGE', 'PUBLISHED', '流浪动物初次接触的三分钟原则', '遇到陌生流浪动物时，第一步不是马上追赶或抱起，而是先观察呼吸、站立状态和周边风险。保持安静、降低动作幅度、准备饮水和临时遮挡，往往比高强度干预更能建立安全感。对幼龄个体或疑似受伤个体，记录发现时间和地点，再联系救助渠道，能明显提高后续接力效率。', NULL, 2047564282341691394, 0, 186, 23, 8, '2026-04-24 09:20:00', '2026-04-23 19:10:00', '2026-04-24 09:20:00'),
    (3000000000000006002, 'KNOWLEDGE', 'PUBLISHED', '为什么救助记录一定要写清地点', '地点不是表单里的装饰项，它决定了后续回访、复查、找回同窝个体和社区沟通是否能继续。建议至少写到街道或小区，再补充明显地标、时间段和出现频率。对经常移动的个体，还可以追加第二、第三次的出现位置，避免下一位接手人从零开始摸索。', NULL, 3000000000000000001, 0, 162, 17, 6, '2026-04-23 14:10:00', '2026-04-22 18:45:00', '2026-04-23 14:10:00'),
    (3000000000000006003, 'ACTIVITY', 'PUBLISHED', '周末领养开放日如何让第一次来访的人更安心', '开放日最怕信息堆得太多，所以现场动线要清楚：签到、看猫狗、咨询、试互动、登记意向，一步一步来。把宠物基本资料提前整理成短卡片，让来访者先建立基本印象，再安排深度沟通，会比一开始就讲完整流程更容易消化。志愿者在这个环节最重要的工作，是帮来访者把问题问出来。', NULL, 2047545148891525121, 0, 134, 12, 5, '2026-04-22 16:30:00', '2026-04-21 10:15:00', '2026-04-22 16:30:00'),
    (3000000000000006004, 'KNOWLEDGE', 'PUBLISHED', '给走失宠物做寻宠海报，最重要的不是排版', '有效的寻宠海报首先要解决识别效率：最近照片、走失时间、区域、明显特征、联系电话，一个都不能少。文字不宜过长，尤其不要把奖励、情绪表达放到最显眼的位置。真正提高找回概率的，是让路人一眼知道它长什么样、最后出现在哪、看见后该打给谁。', NULL, 2047564282341691394, 0, 205, 26, 10, '2026-04-21 11:50:00', '2026-04-20 20:00:00', '2026-04-21 11:50:00'),
    (3000000000000006005, 'STORY', 'PUBLISHED', '雨夜把小煤球带回来的那一晚', '那天晚上雨不大，但停车棚下面一直传来幼猫细细的叫声。志愿者先在原地观察了二十分钟，确认没有母猫返回，才用航空箱和毛巾把小煤球带走。到站后它先躲在角落里，一直到第二天清晨才开始主动进食。很多救助故事不是英雄时刻，而是有人在无人看见时耐心守住了那个夜晚。', NULL, 2047564282341691394, 0, 241, 38, 11, '2026-04-20 08:40:00', '2026-04-19 23:10:00', '2026-04-20 08:40:00'),
    (3000000000000006006, 'STORY', 'PUBLISHED', '阿福第一次学会跟人并肩走路', '阿福刚到站时总习惯用力往前冲，任何新气味都能让它瞬间分心。护理员没有急着追求标准动作，只是每天固定时间带它走短路线、等它回头、再继续前进。两周以后，它第一次在志愿者身边平稳走完整圈。那种被信任慢慢接住的感觉，比完成训练本身更让人开心。', NULL, 3000000000000000001, 0, 198, 31, 9, '2026-04-19 15:15:00', '2026-04-18 18:20:00', '2026-04-19 15:15:00'),
    (3000000000000006007, 'KNOWLEDGE', 'PUBLISHED', '社区喂养点最容易被忽略的清洁细节', '固定喂养并不意味着只把粮放下就结束。食盆回收、饮水更换、残渣清理和拍照留档，是减少投诉和保护喂养点持续性的关键动作。越是想长期稳定做这件事，越要让周围居民看到“有人在认真负责”，而不是留下混乱印象。', NULL, 2047545148891525121, 0, 149, 14, 4, '2026-04-18 10:25:00', '2026-04-17 16:40:00', '2026-04-18 10:25:00'),
    (3000000000000006008, 'ACTIVITY', 'PUBLISHED', '春季绝育宣传周可以怎么做得更接地气', '很多人并不排斥绝育本身，而是不知道流程、价格和术后照护会发生什么。宣传周如果只讲原则，很容易停留在口号层面；如果能加上真实流程、费用区间、术后恢复时间和常见误解，沟通效果会好很多。把专业解释翻译成普通人听得懂的话，是公益活动真正产生作用的开始。', NULL, 2047545148891525121, 0, 121, 11, 3, '2026-04-17 17:30:00', '2026-04-16 14:10:00', '2026-04-17 17:30:00'),
    (3000000000000006009, 'STORY', 'PUBLISHED', '一条旧毛毯，让雪糕愿意从笼角走出来', '雪糕刚收容时一直缩在运输箱最里面，清理和换粮都需要非常慢的动作。后来志愿者把它在楼下常睡的旧毛毯垫进笼内，它开始愿意探头、闻人、再慢慢走出来。熟悉气味对紧张个体的意义，远比我们想象得更大。', NULL, 2047564282341691394, 0, 214, 34, 12, '2026-04-16 09:00:00', '2026-04-15 21:25:00', '2026-04-16 09:00:00'),
    (3000000000000006010, 'KNOWLEDGE', 'PUBLISHED', '把救助信息写成别人能接手的格式', '一条好的交接记录，至少要写明对象特征、当前位置、风险判断、已经做过的处理和下一步建议。不要默认下一位接手人知道你脑海里的背景，也不要把重要信息藏在聊天记录里。结构清楚的记录，本身就是对动物最直接的帮助。', NULL, 3000000000000000001, 0, 173, 18, 7, '2026-04-15 13:45:00', '2026-04-14 19:00:00', '2026-04-15 13:45:00'),
    (3000000000000006011, 'ACTIVITY', 'PUBLISHED', '校园流浪动物分享会，应该讲什么', '面向学生的分享会最好围绕“能做什么”展开，而不是只讲问题有多严重。比如如何辨认求助信号、遇到幼猫时不要马上带走、怎样拍照留档、如何向物业或老师表达诉求。让听众带着可执行的方法离开，比单纯制造情绪波动更有价值。', NULL, 2047545148891525121, 0, 112, 9, 2, '2026-04-14 18:05:00', '2026-04-13 15:50:00', '2026-04-14 18:05:00'),
    (3000000000000006012, 'STORY', 'PUBLISHED', '从躲在人后到主动蹭手，橘子的一个月', '橘子最初对任何伸向它的手都充满戒备，只要有人靠近就迅速退到猫窝最深处。护理员把互动目标拆得很小，先只做换水时的停留，再到递零食、轻声说话、短暂触碰。一个月后，它会在打扫结束时主动走到栏边蹭手。改变并不戏剧化，但每一步都真实。', NULL, 2047564282341691394, 0, 267, 45, 13, '2026-04-13 08:20:00', '2026-04-12 22:05:00', '2026-04-13 08:20:00'),
    (3000000000000006013, 'KNOWLEDGE', 'PUBLISHED', '想帮助流浪动物，先别急着一次做太多', '很多新加入的人一开始就想同时接很多求助，但救助最怕节奏失控。与其一下子铺得很开，不如先稳定一两条流程：记录、联系、转运、复盘。可持续的帮助不靠一时冲刺，而靠每次都能把手上的一件事做好。', NULL, 3000000000000000001, 0, 143, 16, 5, '2026-04-12 12:40:00', '2026-04-11 17:30:00', '2026-04-12 12:40:00'),
    (3000000000000006014, 'ACTIVITY', 'PUBLISHED', '给社区做一次文明喂养说明，需要哪些内容', '一份有效的文明喂养说明，通常要同时回应支持者和质疑者：为什么固定点位、谁负责清洁、出现生病个体怎么办、是否会影响居民。说明里最好带上实际联系人和处理机制，这样它就不是一张空泛海报，而是一份可被追踪的承诺。', NULL, 2047545148891525121, 0, 97, 7, 2, '2026-04-11 16:10:00', '2026-04-10 09:45:00', '2026-04-11 16:10:00'),
    (3000000000000006015, 'KNOWLEDGE', 'PUBLISHED', '救助站里为什么总在说“先隔离观察”', '新进入救助站的个体，外表看起来精神不错，也不代表没有潜在传染风险。隔离观察是为了给动物缓冲、给护理人时间评估，也为了保护已经收容的个体不被交叉感染。把这一步做扎实，后面的护理、社交和领养评估才更稳。', NULL, 2047564282341691394, 0, 187, 24, 6, '2026-04-10 10:00:00', '2026-04-09 18:20:00', '2026-04-10 10:00:00'),
    (3000000000000006016, 'STORY', 'PUBLISHED', '布丁在商铺门口等到天亮', '有人在凌晨收工时发现布丁蜷在卷闸门边，雨一停就抬头看每个经过的人。它并没有立刻跟着上车，只是隔着两米慢慢跟着志愿者走。那段很短的距离像是一场彼此试探，直到它自己跨进航空箱，我们才真正松了口气。', NULL, 3000000000000000001, 0, 223, 29, 8, '2026-04-09 08:55:00', '2026-04-08 23:35:00', '2026-04-09 08:55:00'),
    (3000000000000006017, 'KNOWLEDGE', 'PUBLISHED', '领养沟通里最常见的三个误区', '第一个误区是只聊“喜欢不喜欢”，不聊时间、家庭支持和长期费用；第二个误区是急着给答案，忽略对方真实顾虑；第三个误区是把试养当成交付完成。真正成熟的领养沟通，应该帮助申请人看见未来几个月的真实生活，而不是只停在当下的感动。', NULL, 2047545148891525121, 0, 155, 19, 5, '2026-04-08 14:15:00', '2026-04-07 11:00:00', '2026-04-08 14:15:00'),
    (3000000000000006018, 'ACTIVITY', 'PUBLISHED', '四月社区联动回访安排说明', '本月回访会优先覆盖近期完成领养、刚结束治疗和居民多次反映的点位。每个回访小组至少两人同行，一人负责沟通记录，一人负责现场观察与照片补充。目标不是做一次“打卡式拜访”，而是把后续需要跟进的问题真正带回来。', NULL, 2047564282341691394, 0, 101, 8, 3, '2026-04-07 17:45:00', '2026-04-06 13:20:00', '2026-04-07 17:45:00'),
    (3000000000000006019, 'STORY', 'PUBLISHED', '第一次带月饼喝奶，大家都屏住了呼吸', '月饼太小了，刚到站时连靠近针管都很紧张。志愿者轮班守着，先让它闻，再一点点把温热奶量喂进去。第一口顺下去时，旁边几个人几乎同时松了口气。幼猫救助很考验体力和耐心，但那一点点恢复的迹象，足够支撑大家继续熬夜。', NULL, 2047564282341691394, 0, 231, 37, 10, '2026-04-06 09:10:00', '2026-04-05 22:40:00', '2026-04-06 09:10:00'),
    (3000000000000006020, 'KNOWLEDGE', 'PUBLISHED', '志愿者巡护时，手机里最该准备的四样东西', '除了常见的联系群和地图，建议手机里固定备好现场记录模板、最近的合作医院地址、可复用的求助说明，以及能快速分享的领养或救助表单。真正到现场时，能节省你时间的通常不是更多热情，而是提前准备好的工具。', NULL, 3000000000000000001, 0, 139, 15, 4, '2026-04-05 15:00:00', '2026-04-04 16:20:00', '2026-04-05 15:00:00'),
    (3000000000000006021, 'ACTIVITY', 'PUBLISHED', '救助站开放日路线图和常见问题汇总', '本次开放日将按照签到、参观、互动、咨询四个区块分流。来访者最常问的问题主要集中在领养条件、医疗记录、是否支持试养以及后续回访方式。把这些问题提前整理出来，不仅能减轻现场压力，也能让每位接待志愿者口径一致。', NULL, 2047545148891525121, 0, 118, 10, 4, '2026-04-04 18:30:00', '2026-04-03 12:10:00', '2026-04-04 18:30:00'),
    (3000000000000006022, 'STORY', 'PUBLISHED', '珍珠离站那天，笼门前安静了很久', '珍珠在站里待了很长一段时间，大家已经习惯每天路过时和它打招呼。真正领养成功那天，它没有表现得特别兴奋，只是安静地进了箱子。反而是照顾它的人在关上门后站了很久。好的告别不一定热闹，但会让人真切地感到，这段陪伴没有白费。', NULL, 3000000000000000001, 0, 248, 42, 12, '2026-04-03 09:40:00', '2026-04-02 20:55:00', '2026-04-03 09:40:00'),
    (3000000000000006023, 'STORY', 'DRAFT', '西湖边的一次临时转运记录', '这是一篇待完善的救助故事草稿，准备补充现场照片、转运细节和后续安置情况。', NULL, 2047564282341691394, 0, 0, 0, 0, NULL, '2026-04-25 20:10:00', '2026-04-25 20:10:00'),
    (3000000000000006024, 'KNOWLEDGE', 'DRAFT', '新志愿者入门：第一次值班前的准备清单', '计划整理成一篇给新加入志愿者的值班准备说明，包括穿着、记录、物资和情绪预期。', NULL, 2047564282341691394, 0, 0, 0, 0, NULL, '2026-04-24 21:30:00', '2026-04-24 21:30:00'),
    (3000000000000006025, 'ACTIVITY', 'DRAFT', '五月流浪动物科普角活动预告', '活动内容还在整理中，后续会补充具体时间、摊位互动和志愿者分工。', NULL, 2047564282341691394, 0, 0, 0, 0, NULL, '2026-04-23 22:00:00', '2026-04-23 22:00:00'),
    (3000000000000006026, 'ACTIVITY', 'OFFLINE', '社区旧物义卖支持绝育基金的复盘', '这次义卖带来了稳定的人流和不少第一次接触救助工作的居民，最大的收获其实是让很多人知道“绝育基金”具体会用在哪里。后续我们会把更细的公开说明整理出来，让支持者看见资金流向和实际影响。', NULL, 2047545148891525121, 0, 88, 6, 2, '2026-03-30 10:20:00', '2026-03-29 18:45:00', '2026-04-01 09:10:00'),
    (3000000000000006027, 'KNOWLEDGE', 'OFFLINE', '老年犬领养前必须聊清楚的照护成本', '老年犬并不一定难照顾，但它对家庭节奏、复诊频率和费用规划提出了更明确的要求。把这些现实问题提前说透，反而更能保护领养关系不被理想化期待压垮。', NULL, 3000000000000000001, 0, 74, 5, 1, '2026-03-28 14:40:00', '2026-03-27 16:15:00', '2026-03-31 17:00:00'),
    (3000000000000006028, 'STORY', 'PUBLISHED', '从电话求助到顺利回家，一只走失犬的两天', '第一通电话打来时，对方只说“有一只像是家养犬的狗在超市门口转圈”。后面两天里，志愿者补拍照片、核对芯片、联系物业、扩散信息，最终和主人在站里碰上面。很多成功案例并没有惊险桥段，更多是很多普通步骤一次都没漏。', NULL, 2047564282341691394, 0, 212, 28, 9, '2026-04-02 13:05:00', '2026-04-01 19:40:00', '2026-04-02 13:05:00')
ON DUPLICATE KEY UPDATE
                     `type` = VALUES(`type`),
                     `status` = VALUES(`status`),
                     `title` = VALUES(`title`),
                     `content` = VALUES(`content`),
                     `cover` = VALUES(`cover`),
                     `author_id` = VALUES(`author_id`),
                     `is_discard` = VALUES(`is_discard`),
                     `view_count` = VALUES(`view_count`),
                     `like_count` = VALUES(`like_count`),
                     `share_count` = VALUES(`share_count`),
                     `publish_time` = VALUES(`publish_time`),
